if (info.rle) {
    // Decode image.
    char *dst = (char *)image;
    qint64 num = size;

    while (num > 0) {
        if (s.atEnd()) {
            valid = false;
            break;
        }

        // Get packet header.
        uchar c;
        s >> c;

        uint count = (c & 0x7f) + 1;
        num -= count * pixel_size;
        if (num < 0) {
            valid = false;
            break;
        }

        if (c & 0x80) {
            // RLE pixels.
            assert(pixel_size <= 8);
            char pixel[8];
            s.readRawData(pixel, pixel_size);
            do {
                memcpy(dst, pixel, pixel_size);
                dst += pixel_size;
            } while (--count);
        } else {
            // Raw pixels.
            count *= pixel_size;
            s.readRawData(dst, count);
            dst += count;
        }
    }
} else {
    // Read raw image.
    const int dataRead = s.readRawData((char *)image, size);
    if (dataRead < 0) {
        free(image);
        return false;
    }
    if (dataRead < size) {
        memset(&image[dataRead], 0, size - dataRead);
    }
}
